class Solution { fun maxTwoEvents(events:Array<IntArray>):Int{events.sortBy{it[0]};val heap=java.util.PriorityQueue<IntArray>(compareBy{it[0]});var bestEnded=0;var answer=0;for(event in events){while(heap.isNotEmpty()&&heap.peek()[0]<event[0])bestEnded=maxOf(bestEnded,heap.remove()[1]);answer=maxOf(answer,bestEnded+event[2]);heap.add(intArrayOf(event[1],event[2]))};return answer} }
